.darma-loader-darma-b15-geyser-erupt { --accent: var(--loader-color, #0891b2); --accent-2: var(--loader-secondary-color, #cffafe); width: var(--loader-size, 114px); height: var(--loader-size, 114px); position: relative; }
.darma-loader-darma-b15-geyser-erupt .darma-loader-darma-b15-geyser-erupt__pool { position: absolute; left: 12%; right: 12%; bottom: 5%; height: 15%; border-radius: 50%; background: radial-gradient(ellipse at 50% 40%, var(--accent-2), var(--accent)); }
.darma-loader-darma-b15-geyser-erupt .darma-loader-darma-b15-geyser-erupt__jet { position: absolute; left: 43%; bottom: 12%; width: 14%; height: 0; border-radius: 8px 8px 3px 3px; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b15-geyser-erupt-gey-jet calc(var(--loader-speed, 1s) * 2.2) cubic-bezier(.3, 0, .4, 1) infinite; }
.darma-loader-darma-b15-geyser-erupt i { position: absolute; left: 46%; bottom: 40%; width: 9%; height: 9%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b15-geyser-erupt-gey-spray calc(var(--loader-speed, 1s) * 2.2) ease-out infinite; }
.darma-loader-darma-b15-geyser-erupt i:nth-of-type(1) { --dx: -190%; }
.darma-loader-darma-b15-geyser-erupt i:nth-of-type(2) { --dx: 20%; --dy: -120%; }
.darma-loader-darma-b15-geyser-erupt i:nth-of-type(3) { --dx: 200%; }
@keyframes darma-loader-darma-b15-geyser-erupt-gey-jet { 0%, 26% { height: 0; opacity: .35; } 46% { height: 72%; opacity: 1; } 72% { height: 22%; opacity: .8; } 100% { height: 0; opacity: .35; } }
@keyframes darma-loader-darma-b15-geyser-erupt-gey-spray { 0%, 40% { opacity: 0; transform: translate(0, 0) scale(.4); } 50% { opacity: 1; transform: translate(0, -20%) scale(1); } 100% { opacity: 0; transform: translate(var(--dx, 0%), var(--dy, 40%)) scale(.5); } }

